insert into public.digest_articles (id, feed_id, feed_name, title, url, topic, published_at, fetched_at, full_text, summary)
values
  ('article-umsopch5', 'feed-techcrunch', 'TechCrunch', 'These are the countries moving to ban social media for children', 'https://techcrunch.com/2026/03/06/social-media-ban-children-countries-list/', 'Technology', '2026-03-06T16:00:56.000Z'::timestamptz, '2026-03-08T15:11:45.441Z'::timestamptz, 'Australia was the first country to issue a ban in late 2025, aiming to reduce the pressures and risks that young users may face on social media, including cyberbullying, social media addiction, and exposure to predators.', 'Australia was the first country to issue a ban in late 2025, aiming to reduce the pressures and risks that young users may face on social media, including cyberbullying, social media addiction, and exposure to predators.'),
  ('article-lyd7hmjv', 'feed-ars', 'Ars Technica', 'Apple''s 512GB Mac Studio vanishes, a quiet acknowledgment of the RAM shortage', 'https://arstechnica.com/gadgets/2026/03/apples-512gb-mac-studio-vanishes-a-quiet-acknowledgement-of-the-ram-shortage/', 'Technology', '2026-03-06T15:41:23.000Z'::timestamptz, '2026-03-08T15:11:45.441Z'::timestamptz, 'If the only thing you had to go off was Apple''s string of product announcements this week, you''d have little reason to believe that there is a historic AI-driven memory and storage supply crunch going on. Some products saw RAM and storage increases at the same prices as the products they replaced; others had their prices increased a bit but came with more storage than before as compensation. And there''s the MacBook Neo , which at $599 was priced toward the low end of what Apple-watchers expected. But even a company with Apple''s scale and buying power can''t totally defy gravity. At some point between March 4 and now, Apple quietly removed the 512GB RAM option from its top-tier M3 Ultra Mac Studio desktop. Pricing for the 256GB configuration has also increased, from $1,600 to $2,000. The Tech Specs page on Apple''s support site still acknowledges the existence of the 512GB configuration, but both the Apple Store page and the list of available configurations have removed any mention of it. We''ve asked Apple to comment on the disappearance of the 512GB Mac Studio and will update this article if we receive a response. Read full article Comments', 'If the only thing you had to go off was Apple''s string of product announcements this week, you''d have little reason to believe that there is a historic AI-driven memory and storage supply crunch going on. Some products saw RAM and storage increases at the same prices as the products they replaced; others had their prices increased a bit but came with more storage than before as compensation.'),
  ('article-n6iteuw2', 'feed-ars', 'Ars Technica', 'With Gateway likely gone, where will lunar landers rendezvous with Orion?', 'https://arstechnica.com/space/2026/03/nasa-has-shuffled-its-artemis-rockets-but-what-of-the-lunar-landers/', 'Technology', '2026-03-06T15:20:37.000Z'::timestamptz, '2026-03-08T15:11:45.441Z'::timestamptz, 'Last week, NASA Administrator Jared Isaacman unveiled a major shakeup in the Artemis Program, intended to put the nation on a better path back to the Moon. The changes focused largely on increasing the launch cadence of NASA''s large SLS rocket and putting a greater emphasis on lunar surface activities. Days later, the US Senate indicated that it broadly supported these plans. This is all well and good, but it neglects a critical element of the Artemis program: a lander capable of taking astronauts down to the lunar surface from an orbit around the Moon and back up to rendezvous with Orion. NASA has contracted with SpaceX and Blue Origin to develop these landers, Starship and Blue Moon MK2, respectively. As part of his announcement, Isaacman said a revamped Artemis III mission will now be used to test one or both of these landers near Earth before they are called upon to land humans on the Moon later this decade. Read full article Comments', 'Last week, NASA Administrator Jared Isaacman unveiled a major shakeup in the Artemis Program, intended to put the nation on a better path back to the Moon. The changes focused largely on increasing the launch cadence of NASA''s large SLS rocket and putting a greater emphasis on lunar surface activities.'),
  ('article-acw37ui4', 'feed-darkreading', 'Dark Reading', 'EU Auto Rules Shift Gears on Cybersecurity Standards', 'https://www.darkreading.com/cyber-risk/eu-auto-rules-shift-gears-on-cybersecurity-standards', 'Cybersecurity', '2026-03-06T15:05:55.000Z'::timestamptz, '2026-03-08T15:11:45.441Z'::timestamptz, 'The European Union is taking new precautions as climate change and cybersecurity threats rise across the automotive industry.', 'The European Union is taking new precautions as climate change and cybersecurity threats rise across the automotive industry.'),
  ('article-semrctws', 'feed-techcrunch', 'TechCrunch', 'TriZetto confirms 3.4M people’s health and personal data was stolen during breach', 'https://techcrunch.com/2026/03/06/trizetto-confirms-3-4m-peoples-health-and-personal-data-was-stolen-during-breach/', 'Technology', '2026-03-06T14:28:31.000Z'::timestamptz, '2026-03-08T15:11:45.441Z'::timestamptz, 'Health tech giant TriZetto has confirmed that more than 3.4 million people had personal and health information stolen in a 2024 cyberattack, which the company failed to detect for almost a year.', 'Health tech giant TriZetto has confirmed that more than 3.4 million people had personal and health information stolen in a 2024 cyberattack, which the company failed to detect for almost a year.'),
  ('article-0ssk8go3', 'feed-ars', 'Ars Technica', 'Why are vertebrate eyes so different from those of other animals?', 'https://arstechnica.com/science/2026/03/the-vertebrate-eye-may-have-begun-as-a-cyclops/', 'Technology', '2026-03-06T14:23:59.000Z'::timestamptz, '2026-03-08T15:11:45.441Z'::timestamptz, 'After losing its original eyes, one of our distant ancestors may have done what evolution does best: tinkered with what was available, reshaping a single central visual organ into two new eyes. That''s the idea behind a new theoretical synthesis published in Current Biology. According to the data considered by its authors—a team from the University of Sussex (UK) and Lund University (Sweden)—vertebrate eyes, ours included, may not descend directly from the paired eyes of early bilaterian animals. Instead, they may have been “reinvented” from what was once a single light-sensitive organ that survived an evolutionary detour. Strange eyes “Vertebrate eyes are so fundamentally different from the lateral eyes of other animal groups,” explains Dan-Eric Nilsson , senior author of the study from Lund University and a leading expert in eye evolution. “The key difference is the identity of the main photoreceptor, which is of ciliary nature in the vertebrate eye but rhabdomeric in other animal groups, such as arthropods and cephalopods,” he adds. Read full article Comments', 'After losing its original eyes, one of our distant ancestors may have done what evolution does best: tinkered with what was available, reshaping a single central visual organ into two new eyes. That''s the idea behind a new theoretical synthesis published in Current Biology.'),
  ('article-06ajbh93', 'feed-darkreading', 'Dark Reading', 'Iran''s Cyber-Kinetic War Doctrine Takes Shape', 'https://www.darkreading.com/threat-intelligence/iran-cyber-kinetic-war-doctrine', 'Cybersecurity', '2026-03-06T14:01:11.000Z'::timestamptz, '2026-03-08T15:11:45.441Z'::timestamptz, 'Iran has been hacking IP cameras to plan missile strikes against its enemies, and mounting other attacks on physical assets, showing how cyber and kinetic warfare are fast becoming one in the same.', 'Iran has been hacking IP cameras to plan missile strikes against its enemies, and mounting other attacks on physical assets, showing how cyber and kinetic warfare are fast becoming one in the same.'),
  ('article-gq5ftvu3', 'feed-darkreading', 'Dark Reading', 'Cyberattack on Mexico''s Gov''t Agencies Highlight AI Threat', 'https://www.darkreading.com/application-security/cyberattack-mexico-government-ai-threat', 'Cybersecurity', '2026-03-06T13:37:31.000Z'::timestamptz, '2026-03-08T15:11:45.441Z'::timestamptz, 'Using Anthropic''s Claude, OpenAI''s ChatGPT, and a detailed playbook prompt, a handful of cyberattackers reportedly gained access to government agencies and its citizens'' data.', 'Using Anthropic''s Claude, OpenAI''s ChatGPT, and a detailed playbook prompt, a handful of cyberattackers reportedly gained access to government agencies and its citizens'' data.'),
  ('article-7q5wo7ea', 'feed-mit', 'MIT Tech Review', 'The Download: 10 things that matter in AI, plus Anthropic’s plan to sue the Pentagon', 'https://www.technologyreview.com/2026/03/06/1133989/the-download-10-things-that-matter-in-ai-anthropics-plan-sue-pentagon/', 'AI', '2026-03-06T13:10:00.000Z'::timestamptz, '2026-03-08T15:11:45.441Z'::timestamptz, 'This is today&#8217;s edition of The Download , our weekday newsletter that provides a daily dose of what&#8217;s going on in the world of technology. Coming soon: our 10 Things That Matter in AI Right Now For years, MIT Technology Review&#8217;s newsroom has been ahead of the curve, tracking the developments in AI that matter and explaining what they mean. Now, our world-leading AI team is creating something definitive: the 10 Things That Matter in AI Right Now. Publishing in April to be launched at our flagship AI event, EmTech AI, this special report will reveal what our expert journalists are tracking most closely, what breakthroughs have excited them, and what transformations they see on the horizon. It&#8217;s our authoritative snapshot of where AI is heading in the year ahead—a curated expert list of 10 technologies, emerging trends, bold ideas, and powerful movements reshaping our world. Attendees at EmTech AI will get much more than an exclusive heads-up of what made our 10 Things That Matter in AI Right Now list. We’re at a pivotal moment as AI moves from pilot testing into core business infrastructure, and to reflect that we’ve curated a program that will help you navigate what’s going on, and get ahead of what’s coming next. We’ll hear from top leaders at OpenAI, Walmart, General Motors, Poolside, MIT, the Allen Institute for AI (Ai2) and SAG-AFTRA. Topics will include everything from how organizations are preparing for AI agents to how AI will change the future of human expression. As well as networking with speakers, you’ll have the chance to mingle with MIT Technology Review’s editors too. Download readers get 10% off tickets , so what are you waiting for? See you there! The must-reads I’ve combed the internet to find you today’s most fun/important/scary/fascinating stories about technology. 1 Anthropic says it plans to sue the Pentagon It believes the DoD’s ban on its software is unlawful. ( BBC ) + CEO Dario Amodei has nonetheless apologized for a leaked memo criticizing Trump. ( Axios ) + Trump, meanwhile, says he fired Anthropic “like dogs.” ( The Guardian ) + In happier news for Anthropic, its models can remain in Microsoft products. ( CNBC ) 2 The Pentagon has been secretly testing OpenAI models for years Which shows exactly how effective OpenAI’s ban on military use of its models has been. ( Wired $) 3 A new lawsuit says Trump’s TikTok deal helped firms that &#8216;personally enriched&#8217; him The suit aims to reverse the sale of the app’s US operations. ( CBS News ) + It could shed light on the majority American-owned joint venture for TikTok. ( Reuters ) 4 AI could give smart homes a reboot Google and Amazon are betting on smarter assistants—but not everyone’s convinced ( NYT ) 5 Iran has struck Amazon data centers, rattling the Gulf’s AI ambitions The first military hit on a US hyperscaler has shaken the region’s tech sector. ( FT $) + The conflict has thrown a spotlight on AI’s current use in warfare—and what’s next. ( Nature ) 6 Trump and tech CEOs have promised to protect consumers from AI’s energy costs Google, Microsoft, Meta, Amazon, OpenAI, Oracle and xAI have all signed the pledge. ( Axios ) + But what is AI’s true energy footprint? We did the math. ( MIT Technology Review ) 7 Meta’s getting sued over surveillance through smart glasses The suit claims Meta misled users over the devices’ privacy features. ( TechCrunch ) 8 There’s a new field of study: researching ‘AI societies’ Scientists are examining human behavior without even involving humans. ( Nature ) + Hundreds of AI agents built their own society in Minecraft. ( MIT Technology Review ) 9 Oh great, teenage boys are using ChatGPT to chat up girls Of all the things to outsource to AI, flirting surely ain’t it. ( Vox ) 10 The mythical Nintendo PlayStation has a new home The US National Video Museum has bought the fabled console’s development kit. ( Engadget ) Quote of the day “It’s sort of bitterly ironic.” —Dean Ball, a former Trump administration AI adviser, tells Politico that the Anthropic spat contradicts the president’s pledge to cut bureaucratic red tape for tech. One more thing KATHERINE LAM These scientists are working to extend the life span of pet dogs—and their owners Gavesh’s journey began with a Facebook job advert promising a better life. Instead, he was trafficked into &#8220;pig butchering&#8221;—a form of fraud where scammers build close relationships with online targets to extract money. We spoke to Gavesh and five other workers from inside the scam industry, as well as anti-trafficking experts and technology specialists. Their testimony reveals how global tech platforms have industrialized this criminal trade—and why those same companies now hold the key to dismantling it. Read the full story . —Peter Guest and Emily Fishb ein We can still have nice things A place for comfort, fun and distraction to brighten up your day. (Got any ideas? Drop me a line o r skeet &#8217;em at me .) + The Blood Moon of March 3 was sublime. + Orysia Zabeida’s imperfect animations , drawn frame-by-frame from memory, are hypnotizing. + This stunning snap of a white whale calf scooped the top prize at the World Nature Photography Awards. + Two &#8220;Lazarus&#8221; marsupial species just came back from the dead in a big win for biodiversity.', 'This is today’s edition of The Download, our weekday newsletter that provides a daily dose of what’s going on in the world of technology. Coming soon: our 10 Things That Matter in AI Right Now For years, MIT Technology Review’s newsroom has been ahead of the curve, tracking the developments in AI that matter and explaining what they mean.'),
  ('article-juo4hkpi', 'feed-ars', 'Ars Technica', 'Tech industry is in tariff hell, even if refunds are automated', 'https://arstechnica.com/tech-policy/2026/03/tech-industry-is-in-tariff-hell-even-if-refunds-are-automated/', 'Technology', '2026-03-06T12:20:40.000Z'::timestamptz, '2026-03-08T15:11:45.441Z'::timestamptz, 'It has been two weeks since the Supreme Court blocked Donald Trump''s emergency tariffs , but an estimated 300,000 US businesses still have no idea if or when they will receive refunds. Economists have estimated that more than $175 billion was unlawfully collected, and the US could end up owing substantially more than that the longer the refund process is dragged out, since the US must pay back daily interest on the funds. According to the Cato Institute , a libertarian think tank, a conservative estimate showed that "$700 million in interest is added to the final bill every month that the government delays tariff refunds, or around $23 million per day." The US is aware that interest is compounding daily on tariffs, as the Trump administration argued against an injunction that would have temporarily blocked the tariffs much sooner by noting that no one would be harmed, since tariffs would be repaid with interest if deemed unlawful. However, now that the court has ruled against tariffs, the Trump administration seems to be dragging its feet in finding a way to return all the ill-gotten funds. Read full article Comments', 'It has been two weeks since the Supreme Court blocked Donald Trump''s emergency tariffs, but an estimated 300,000 US businesses still have no idea if or when they will receive refunds. Economists have estimated that more than $175 billion was unlawfully collected, and the US could end up owing substantially more than that the longer the refund process is dragged out, since the US must pay back daily interest on the funds.')
